import { Button } from '@refy-design/web';
import { Trace } from '@refy-design/web';
import { useState } from 'react';
const stack = { display: 'grid', gap: 'var(--space-4)', minWidth: 0 } as const;
function TraceExample() {
  const [complete, setComplete] = useState(false);
  return (
    <div style={stack}>
      <Trace
        steps={[
          {
            id: 'read',
            title: 'Read materials',
            status: 'complete',
            duration: '120 ms',
            detail: '{"files": 3, "result": "ok"}',
          },
          {
            id: 'prepare',
            title: 'Prepare preview',
            status: complete ? 'complete' : 'running',
            detail: complete ? '{"result": "ready"}' : '{"result": "in progress"}',
          },
        ]}
      />
      <Button onClick={() => setComplete(!complete)}>
        {complete ? 'Restart run' : 'Finish run'}
      </Button>
    </div>
  );
}
export function Example() {
  return <TraceExample />;
}

